 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';
-</script>
+const root=document.querySelector('#game');
+const scene=new THREE.Scene();scene.background=new THREE.Color(0x84cff3);scene.fog=new THREE.Fog(0x84cff3,115,220);
+const camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,.1,500);
+const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.14;root.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xe4f8ff,0x47604c,2.1));const sun=new THREE.DirectionalLight(0xfff1d0,3.2);sun.position.set(-35,75,28);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;scene.add(sun);
+const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
+const mats={grass:mat(0x62b94f),grass2:mat(0x4ea948),sand:mat(0xdac27d),road:mat(0x303b4b),roadEdge:mat(0xeff4f4),yellow:mat(0xffd847),blue:mat(0x289ce8),red:mat(0xff5366),white:mat(0xf6f5e8),dark:mat(0x192333),rubber:mat(0x151b26),metal:mat(0x728090,.45,.45),wood:mat(0x996342),roof:mat(0xee684c),leaf:mat(0x299751),cyan:mat(0x54f0fa,.3,.2)};
+const water=new THREE.Mesh(new THREE.PlaneGeometry(600,600),mat(0x277dac,.33));water.rotation.x=-Math.PI/2;water.position.y=-3.6;scene.add(water);
+function pathPoint(t){const a=t*Math.PI*2;return new THREE.Vector3(48*Math.sin(a)+5*Math.sin(2*a),.45,39*Math.cos(a)+4*Math.sin(3*a))}
+function pathTangent(t){const e=.0005;return pathPoint(t+e).sub(pathPoint(t-e)).normalize()}
+function pathNormal(t){const v=pathTangent(t);return new THREE.Vector3(-v.z,0,v.x)}
+const N=400, trackWidth=15;
+function makeIsland(){const seg=128,rings=12,verts=[],colors=[],indices=[];for(let j=0;j<=rings;j++){const f=j/rings,r=f*83;for(let i=0;i<=seg;i++){const a=i/seg*Math.PI*2;const wobble=1+Math.sin(a*5)*.018+Math.cos(a*9)*.012;const rr=r*wobble;verts.push(Math.cos(a)*rr,-1.7+Math.sin(f*Math.PI)*.9,Math.sin(a)*rr);const c=new THREE.Color(f>.91?0x9bd5df:f>.84?0xd7c27c:(i%4===0&&j%3===0?0x58aa48:0x63bd51));colors.push(c.r,c.g,c.b)}}for(let j=0;j<rings;j++)for(let i=0;i<seg;i++){const a=j*(seg+1)+i,b=a+seg+1;indices.push(a,b,a+1,b,b+1,a+1)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));m.receiveShadow=true;scene.add(m)}makeIsland();
+function ribbon(width,y,material,offset=0){const v=[],idx=[];for(let i=0;i<=N;i++){const t=i/N,p=pathPoint(t),n=pathNormal(t);p.y=y;const a=p.clone().addScaledVector(n,offset-width/2),b=p.clone().addScaledVector(n,offset+width/2);v.push(a.x,a.y,a.z,b.x,b.y,b.z);if(i<N){const k=i*2;idx.push(k,k+1,k+2,k+1,k+3,k+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();const mesh=new THREE.Mesh(g,material);mesh.receiveShadow=true;mesh.castShadow=false;scene.add(mesh);return mesh}
+ribbon(trackWidth+1.6,.18,mats.roadEdge);ribbon(trackWidth,.23,mats.road);ribbon(.24,.25,mat(0x536273),0);
+// Alternating curb blocks make every bend readable.
+for(let i=0;i<160;i++){const t=i/160,p=pathPoint(t),n=pathNormal(t);for(const side of [-1,1]){const curb=new THREE.Mesh(new THREE.BoxGeometry(1.05,.24,.68),i%2?mats.white:mats.red);curb.position.copy(p).addScaledVector(n,side*(trackWidth/2+.24));curb.position.y=.38;curb.rotation.y=Math.atan2(pathTangent(t).x,pathTangent(t).z);curb.castShadow=true;scene.add(curb)}}
+// Simple island props: tropical trees, colorful outpost sheds, balloons, cliff markers.
+function tree(x,z,scale=1){const group=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.28*scale,.42*scale,3.8*scale,7),mats.wood);trunk.position.y=1.1*scale;trunk.castShadow=true;group.add(trunk);for(let i=0;i<5;i++){const crown=new THREE.Mesh(new THREE.ConeGeometry((2.3-i*.2)*scale,3.0*scale,7),i%2?mats.leaf:mats.grass2);crown.position.set(0,(3.0+i*.76)*scale,0);crown.rotation.y=i*.63;crown.castShadow=true;group.add(crown)}group.position.set(x,-1,z);scene.add(group)}
+function hut(x,z,color=0xe87253,scale=1){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.BoxGeometry(5*scale,3.2*scale,4*scale),mat(color));body.position.y=1.4*scale;body.castShadow=true;g.add(body);const roof=new THREE.Mesh(new THREE.ConeGeometry(4*scale,2.5*scale,4),mats.roof);roof.position.y=4.2*scale;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);const door=new THREE.Mesh(new THREE.BoxGeometry(.85*scale,1.7*scale,.14),mats.dark);door.position.set(0,.82*scale,2.04*scale);g.add(door);const window=new THREE.Mesh(new THREE.BoxGeometry(1*scale,.8*scale,.16),mats.cyan);window.position.set(-1.35*scale,1.9*scale,2.05*scale);g.add(window);g.position.set(x,-1,z);scene.add(g)}
+for(let i=0;i<37;i++){const a=i*2.399,rad=64+(i%5)*3;tree(Math.cos(a)*rad,Math.sin(a)*rad,.72+(i%4)*.1)}
+hut(-22,-7,0xe87854,1.2);hut(20,9,0x4793c2,1.05);hut(-7,28,0xd7a64e,.82);
+// Hills and a little broadcast tower decorate the horizon.
+for(const [x,z,r,h,c] of [[-67,18,14,20,0x5c9b57],[58,-44,17,25,0x5c9b57],[-18,-65,15,19,0x6da052],[68,33,12,17,0x67954c]]){const hill=new THREE.Mesh(new THREE.ConeGeometry(r,h,7),mat(c));hill.position.set(x,-1+h/2,z);hill.rotation.y=.4;hill.castShadow=true;scene.add(hill)}
+const tower=new THREE.Group();const pole=new THREE.Mesh(new THREE.CylinderGeometry(.28,.4,14,8),mats.metal);pole.position.y=6;pole.castShadow=true;tower.add(pole);const dish=new THREE.Mesh(new THREE.SphereGeometry(2.2,12,8,0,Math.PI*2,0,Math.PI/2),mats.white);dish.position.y=13;tower.add(dish);tower.position.set(0,-1,-18);scene.add(tower);
