function buildKart(color,accent,number){const g=new THREE.Group();const bodyMat=mat(color,.35,.08),accentMat=mat(accent,.4,.05);
 const low=new THREE.Mesh(new THREE.BoxGeometry(1.65,.52,2.7),bodyMat);low.position.y=.66;low.castShadow=true;g.add(low);
 const nose=new THREE.Mesh(new THREE.BoxGeometry(1.25,.25,.68),accentMat);nose.position.set(0,.61,1.58);nose.castShadow=true;g.add(nose);
 const seat=new THREE.Mesh(new THREE.BoxGeometry(1.05,.78,.85),mats.dark);seat.position.set(0,1.02,-.2);seat.castShadow=true;g.add(seat);
 const spoiler=new THREE.Mesh(new THREE.BoxGeometry(1.7,.16,.32),accentMat);spoiler.position.set(0,1.15,-1.34);g.add(spoiler);for(const x of [-.68,.68]){const fin=new THREE.Mesh(new THREE.BoxGeometry(.13,.4,.18),accentMat);fin.position.set(x,1.36,-1.34);g.add(fin)}
 const wheels=[];for(const x of [-.94,.94])for(const z of [-.9,.94]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.3,12),mats.rubber);w.rotation.z=Math.PI/2;w.position.set(x,.47,z);w.castShadow=true;g.add(w);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.32,10),accentMat);hub.rotation.z=Math.PI/2;hub.position.copy(w.position);g.add(hub);wheels.push(w)}
 const driver=new THREE.Group();const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.37,.63,4,8),mat(color===0xff4c5f?0x29b9c9:accent));torso.position.y=1.65;torso.castShadow=true;driver.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.48,16,12),mat(0xffc48b));head.position.y=2.35;head.castShadow=true;driver.add(head);const helmet=new THREE.Mesh(new THREE.SphereGeometry(.54,16,10,0,Math.PI*2,0,Math.PI*.56),accentMat);helmet.position.y=2.56;helmet.castShadow=true;driver.add(helmet);const visor=new THREE.Mesh(new THREE.BoxGeometry(.7,.15,.12),mat(0x13233a,.2,.3));visor.position.set(0,2.38,.42);driver.add(visor);const badge=new THREE.Mesh(new THREE.BoxGeometry(.32,.23,.06),mats.white);badge.position.set(0,1.66,.385);driver.add(badge);driver.position.z=-.03;g.add(driver);
 const num=new THREE.Mesh(new THREE.BoxGeometry(.58,.42,.08),mats.white);num.position.set(0,.78,-1.39);g.add(num);
 g.userData={wheels,number,bodyMat};return g}
const racerColors=[[0xff4c5f,0xffd74c],[0x2dcbe4,0xf6f7ed],[0xffb52e,0x5639be],[0x9a67ff,0x7affbb]];
const player={progress:0,lateral:0,latVel:0,speed:0,boost:28,drift:0,boosts:0,lap:1,finished:false};
const playerKart=buildKart(...racerColors[0],1);scene.add(playerKart);
const bots=[0,1,2].map((i)=>{const kart=buildKart(...racerColors[i+1],i+2);scene.add(kart);return {kart,progress:[.018,-.033,-.071][i],lateral:[-2.8,2.6,-2.5][i],speed:26+Math.random()*2,hit:0,finished:false}});
function placeKart(kart,progress,lateral=0){const t=((progress%1)+1)%1,p=pathPoint(t),tan=pathTangent(t),normal=pathNormal(t);p.addScaledVector(normal,lateral);kart.position.copy(p);kart.position.y=.25;kart.rotation.y=Math.atan2(tan.x,tan.z)}
function makeBox(t,lane){const g=new THREE.Group();const cube=new THREE.Mesh(new THREE.BoxGeometry(1.45,1.45,1.45),new THREE.MeshStandardMaterial({color:0xffe45c,emissive:0x684d00,emissiveIntensity:.75,roughness:.24,metalness:.08}));cube.castShadow=true;g.add(cube);const ring=new THREE.Mesh(new THREE.TorusGeometry(.92,.08,8,24),mats.cyan);ring.rotation.x=Math.PI/2;g.add(ring);const p=pathPoint(t).addScaledVector(pathNormal(t),lane);p.y=1.7;g.position.copy(p);scene.add(g);return {mesh:g,t,lane,active:true,respawn:0}}
const itemBoxes=Array.from({length:10},(_,i)=>makeBox(.075+i*.091,(i%2?3.4:-3.4)));
// Floating supply blimps mark the loop from far away.
for(let i=0;i<3;i++){const a=i*2.1;const balloon=new THREE.Mesh(new THREE.SphereGeometry(2.4,18,14),mat([0xff715e,0x67d9f4,0xffd451][i],.4));balloon.scale.set(1,1.3,1);balloon.position.set(Math.cos(a)*57,15,Math.sin(a)*58);scene.add(balloon);const string=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,6,5),mats.white);string.position.set(balloon.position.x,10,balloon.position.z);scene.add(string)}

