for(let i=0;i<3;i++){const a=i*2.1;const balloon=new THREE.Mesh(new THREE.SphereGeometry(2.4,18,14),mat([0xff715e,0x67d9f4,0xffd451][i],.4));balloon.scale.set(1,1.3,1);balloon.position.set(Math.cos(a)*57,15,Math.sin(a)*58);scene.add(balloon);const string=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,6,5),mats.white);string.position.set(balloon.position.x,10,balloon.position.z);scene.add(string)}
const keys=new Set();let running=false,countdown=0,raceTime=0,lastTime=0,toastTimer=0,boosting=false,currentItem='⚡',shells=[];const circumference=310;
const ui={hud:document.querySelector('#hud'),intro:document.querySelector('#intro'),result:document.querySelector('#result'),lap:document.querySelector('#lap'),timer:document.querySelector('#timer'),speed:document.querySelector('#speed'),place:document.querySelector('#place'),boost:document.querySelector('#boostFill'),item:document.querySelector('#itemCard'),toast:document.querySelector('#toast'),raceStatus:document.querySelector('#raceStatus')};
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.5}
function startRace(){if(running)return;running=true;raceTime=0;countdown=2.8;ui.intro.classList.add('hidden');ui.hud.style.display='block';player.progress=0;player.lateral=0;player.latVel=0;player.speed=0;player.boost=28;player.lap=1;player.finished=false;player.boosts=0;bots.forEach((b,i)=>{b.progress=[.018,-.033,-.071][i];b.speed=25.5+i*.8;b.hit=0});showToast('3  •  GET READY!');lastTime=performance.now()}
document.querySelector('#start').addEventListener('click',startRace);document.querySelector('#again').addEventListener('click',()=>{ui.result.classList.remove('show');player.progress=0;bots.forEach((b,i)=>b.progress=[.018,-.033,-.071][i]);running=false;startRace()});
